'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { cn } from '@/components/lib/utils';

type Cor = 'teal' | 'orange' | 'yellow' | 'gray';

const cores: Record<Cor, string> = {
  teal: 'bg-teal-50 border-teal-400 text-teal-700',
  orange: 'bg-orange-50 border-orange-400 text-orange-700',
  yellow: 'bg-amber-50 border-amber-400 text-amber-700',
  gray: 'bg-slate-100 border-slate-400 text-slate-700'
};

const disciplinas: Record<string, Cor> = {
  Matemática: 'teal',
  Física: 'orange',
  Inglês: 'yellow',
  Português: 'gray'
};

const dias = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex'];
const horas = ['15:00', '16:30', '18:00'];

// [dia, hora, disciplina, professor/sala]
const aulas: [number, number, string, string][] = [
  [0, 0, 'Matemática', 'Prof. Rita · Sala 1'],
  [0, 0, 'Física', 'Prof. Nuno · Sala 2'],
  [1, 0, 'Física', 'Prof. Nuno · Sala 2'],
  [1, 0, 'Português', 'Prof. Ana · Sala 3'],
  [2, 0, 'Matemática', 'Prof. Rita · Sala 1'],
  [2, 0, 'Matemática', 'Prof. Hugo · Sala 4'],
  [3, 0, 'Português', 'Prof. Ana · Sala 3'],
  [3, 0, 'Inglês', 'Prof. Sara · Sala 2'],
  [4, 0, 'Inglês', 'Prof. Sara · Sala 2'],
  [0, 1, 'Física', 'Prof. Nuno · Sala 2'],
  [0, 1, 'Matemática', 'Prof. Hugo · Sala 4'],
  [1, 1, 'Inglês', 'Prof. Sara · Sala 1'],
  [1, 1, 'Inglês', 'Prof. Sara · Sala 3'],
  [2, 1, 'Física', 'Prof. Nuno · Sala 2'],
  [2, 1, 'Matemática', 'Prof. Rita · Sala 1'],
  [3, 1, 'Inglês', 'Prof. Sara · Sala 2'],
  [3, 1, 'Física', 'Prof. Nuno · Sala 4'],
  [4, 1, 'Português', 'Prof. Ana · Sala 3'],
  [0, 2, 'Inglês', 'Prof. Sara · Sala 1'],
  [1, 2, 'Matemática', 'Prof. Rita · Sala 1'],
  [2, 2, 'Física', 'Prof. Nuno · Sala 2'],
  [3, 2, 'Português', 'Prof. Ana · Sala 3'],
  [4, 2, 'Matemática', 'Prof. Hugo · Sala 4']
];

const tarefasIniciais = [
  'Lançar sumários de ontem',
  'Ligar ao encarregado do João',
  'Confirmar sala 4 para sexta',
  'Enviar recibos de novembro',
  'Marcar teste de Física',
  'Rever faltas da semana'
];

export default function Page() {
  const [vista, setVista] = useState('Semana');
  const [filtro, setFiltro] = useState<string | null>(null);
  const [feitas, setFeitas] = useState<string[]>([]);

  const toggle = (t: string) =>
    setFeitas((f) => (f.includes(t) ? f.filter((x) => x !== t) : [...f, t]));

  return (
    <div className='flex min-h-screen bg-teal-400/80 p-4 gap-4'>
      {/* Rail lateral */}
      <aside className='flex w-16 flex-col items-center gap-4 rounded-2xl bg-teal-500 py-4'>
        <div className='flex size-10 items-center justify-center rounded-full bg-slate-800 font-bold text-amber-400'>
          CE
        </div>
        {['Horário', 'Alunos', 'Pagamentos', 'Mensagens'].map((n, i) => (
          <button
            key={n}
            title={n}
            className={cn('size-6 rounded-full bg-white', i !== 0 && 'opacity-70')}
          />
        ))}
      </aside>

      {/* Painel de tarefas */}
      <section className='hidden w-64 flex-col overflow-hidden rounded-2xl bg-white shadow-lg lg:flex'>
        <div className='flex items-center justify-between bg-teal-500 px-4 py-3 text-white'>
          <span className='font-semibold'>Tarefas</span>
          <span className='rounded-full bg-white/30 px-2 text-sm'>
            {tarefasIniciais.length - feitas.length}
          </span>
        </div>
        <ul className='space-y-1 p-3'>
          {tarefasIniciais.map((t) => (
            <li key={t}>
              <label className='flex cursor-pointer items-center justify-between gap-2 rounded-lg px-2 py-2 text-sm hover:bg-teal-50'>
                <span className={cn(feitas.includes(t) && 'text-muted-foreground line-through')}>
                  {t}
                </span>
                <Checkbox checked={feitas.includes(t)} onCheckedChange={() => toggle(t)} />
              </label>
            </li>
          ))}
        </ul>
      </section>

      {/* Calendário */}
      <main className='flex flex-1 flex-col overflow-hidden rounded-2xl bg-white shadow-lg'>
        <header className='px-6 pt-5 pb-3'>
          <h1 className='text-3xl font-extrabold text-slate-800'>Horário</h1>
        </header>

        <div className='flex flex-wrap items-center justify-between gap-3 border-y border-teal-100 bg-teal-50/40 px-6 py-4'>
          <div className='flex gap-2'>
            {['Semana', 'Mês', 'Dia'].map((v) => (
              <Button
                key={v}
                size='sm'
                variant={vista === v ? 'default' : 'outline'}
                className={cn(
                  'rounded-lg px-5',
                  vista === v ? 'bg-teal-500 text-white hover:bg-teal-600' : 'border-teal-300 text-teal-700'
                )}
                onClick={() => setVista(v)}
              >
                {v}
              </Button>
            ))}
          </div>
          <div className='flex flex-wrap gap-2'>
            {Object.keys(disciplinas).map((d) => (
              <Button
                key={d}
                size='sm'
                variant='outline'
                className={cn(
                  'rounded-lg border-teal-300 text-teal-700',
                  filtro === d && 'bg-teal-100'
                )}
                onClick={() => setFiltro(filtro === d ? null : d)}
              >
                {d}
              </Button>
            ))}
          </div>
        </div>

        <div className='overflow-auto p-4'>
          <div className='grid min-w-[720px] grid-cols-[60px_repeat(5,1fr)]'>
            <div />
            {dias.map((d) => (
              <div key={d} className='pb-2 text-center text-sm font-semibold text-teal-700'>
                {d}
              </div>
            ))}
            {horas.map((h, hi) => (
              <div key={h} className='contents'>
                <div className='border-t border-teal-200 pt-3 text-xs text-slate-500'>{h}</div>
                {dias.map((_, di) => (
                  <div
                    key={di}
                    className='space-y-2 border-t border-l border-teal-200 p-2'
                  >
                    {aulas
                      .filter(([d, hr, disc]) => d === di && hr === hi && (!filtro || filtro === disc))
                      .map(([, , disc, info], i) => (
                        <button
                          key={i}
                          onClick={() => toast(`${disc} · ${dias[di]} ${h}`, { description: info })}
                          className={cn(
                            'w-full rounded-lg border-l-4 px-3 py-2 text-left transition hover:brightness-95',
                            cores[disciplinas[disc]]
                          )}
                        >
                          <div className='text-sm font-semibold'>{disc}</div>
                          <div className='text-xs opacity-80'>{info}</div>
                        </button>
                      ))}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  );
}
